package com.hau.ai.infrastructure.rabbitmq;import com.hau.ai.application.service.AiJobProcessor;import com.hau.ai.domain.exception.ProviderException;import com.rabbitmq.client.Channel;import java.io.IOException;import java.util.UUID;import org.slf4j.*;import org.springframework.amqp.core.Message;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public class AiJobConsumer{private static final Logger log=LoggerFactory.getLogger(AiJobConsumer.class);private final AiJobProcessor processor;private final RabbitTemplate rabbit;private final int max;public AiJobConsumer(AiJobProcessor p,RabbitTemplate r,@Value("${ai.rabbitmq.max-retries}")int m){processor=p;rabbit=r;max=m;}@RabbitListener(queues=RabbitConfiguration.QUEUE,concurrency="${ai.rabbitmq.concurrency:1}")public void consume(EventEnvelope e,Message m,Channel c)throws IOException{long tag=m.getMessageProperties().getDeliveryTag();UUID job=UUID.fromString(e.payload().get("jobId").asText());try{processor.process(e.eventId(),job,e.correlationId());c.basicAck(tag,false);}catch(ProviderException x){int attempt=((Number)m.getMessageProperties().getHeaders().getOrDefault("x-retry-count",0)).intValue()+1;m.getMessageProperties().setHeader("x-retry-count",attempt);log.warn("AI provider call failed; jobId={}, attempt={}",job,attempt);if(attempt>=max){processor.failAfterRetries(e.eventId(),job,e.correlationId(),"Provider retry exhausted");rabbit.send("ai.dlx",RabbitConfiguration.DLQ,m);}else rabbit.send("ai.retry.exchange",RabbitConfiguration.RETRY,m);c.basicAck(tag,false);}}
}
